insert into public.scenarios (id, title, persona, persona_role, area, difficulty, minutes, description, competencies) values ('s1', 'Il rinnovo con sconto', 'Roberto, titolare di un negozio', 'Compratore', 'Vendite', 'Difficile', 6, 'Il cliente rinnova la polizza Casa ma chiede il 15% di sconto, oltre il massimo consentito.', array['Argomentare con i dati','Generare opzioni','Interessi e posizioni']::text[]);
insert into public.scenarios (id, title, persona, persona_role, area, difficulty, minutes, description, competencies) values ('s2', 'La chiamata per trattenere il cliente', 'Anna, cliente da 6 anni', 'Cliente', 'Vendite', 'Media', 5, 'La cliente ha ricevuto un''offerta da un concorrente e vuole disdire.', array['Ascolto attivo','Gestire le obiezioni']::text[]);
insert into public.scenarios (id, title, persona, persona_role, area, difficulty, minutes, description, competencies) values ('s3', 'Il cliente arrabbiato', 'Franco, sinistro non rimborsato', 'Cliente', 'Servizio clienti', 'Difficile', 5, 'Il rimborso è in ritardo di tre settimane. Franco alza la voce dal primo secondo.', array['Ascolto attivo','Tono di voce']::text[]);
insert into public.scenarios (id, title, persona, persona_role, area, difficulty, minutes, description, competencies) values ('s4', 'Il riscontro difficile', 'Stefano, collaboratore', 'Collaboratore', 'Manager', 'Media', 8, 'Devi dire a un collaboratore che i suoi risultati del trimestre non bastano.', array['Tono di voce','Interessi e posizioni']::text[]);
insert into public.scenarios (id, title, persona, persona_role, area, difficulty, minutes, description, competencies) values ('s5', 'La prima telefonata', 'Laura, potenziale cliente', 'Cliente', 'Neoassunti', 'Facile', 4, 'Presenta Auto Plus in due minuti a chi non ti conosce.', array['Argomentare con i dati','Ascolto attivo']::text[]);
insert into public.scenarios (id, title, persona, persona_role, area, difficulty, minutes, description, competencies) values ('s6', 'Il collega che non collabora', 'Matteo, ufficio sinistri', 'Collega', 'Servizio clienti', 'Media', 5, 'Ti serve una pratica entro domani, ma il collega ha altre priorità.', array['Generare opzioni','Interessi e posizioni']::text[]);
insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r1', 's1', 'm2', '2026-10-24', 232, 4.2, '{"Ascolto attivo":4.5,"Tono di voce":4,"Argomentare con i dati":4.2,"Generare opzioni":3.8,"Interessi e posizioni":4.4}'::jsonb, '[{"at":"00:42","competency":"Ascolto attivo","kind":"positivo","quote":"Capisco, un aumento di 50 euro non fa piacere. Posso spiegarle da dove arriva?","text":"Hai riformulato la richiesta del cliente prima di rispondere: si è sentito capito."},{"at":"01:35","competency":"Argomentare con i dati","kind":"positivo","quote":"Nella sua zona i sinistri per allagamento sono cresciuti dell''8%.","text":"Citare il +8% di sinistri in zona ha reso l''aumento comprensibile."},{"at":"02:50","competency":"Generare opzioni","kind":"migliora","quote":"Va bene, le applico il 10%: è il massimo che posso fare.","text":"Hai offerto subito lo sconto massimo. Prova prima a proporre la franchigia più alta."},{"at":"03:40","competency":"Interessi e posizioni","kind":"positivo","quote":"Per lei conta più il totale o la rata mensile?","text":"Hai scoperto che al cliente interessa la rata mensile, non il totale annuo."}]'::jsonb);
insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r6', 's1', 'm1', '2026-10-23', 298, 4.6, '{"Argomentare con i dati":4.7,"Generare opzioni":4.5,"Interessi e posizioni":4.6}'::jsonb, '[{"at":"00:30","competency":"Interessi e posizioni","kind":"positivo","quote":"Prima di parlare di prezzo: cosa è cambiato per il negozio quest''anno?","text":"Sei partita dal cliente, non dallo sconto: la trattativa si è aperta subito."},{"at":"02:15","competency":"Generare opzioni","kind":"positivo","quote":"Posso alzare la franchigia a 500 euro: il premio scende del 7%.","text":"Un''alternativa concreta allo sconto, con il numero giusto."},{"at":"04:05","competency":"Argomentare con i dati","kind":"migliora","quote":"Il listino è questo, purtroppo.","text":"Qui il listino è suonato come un muro: aggiungi il perché dell''aumento."}]'::jsonb);
insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r5', 's2', 'm3', '2026-10-23', 265, 3.6, '{"Ascolto attivo":3.9,"Gestire le obiezioni":3.3}'::jsonb, '[{"at":"00:35","competency":"Ascolto attivo","kind":"positivo","quote":"Mi racconta cosa le hanno offerto, esattamente?","text":"Domanda aperta al momento giusto: Anna ha spiegato tutta l''offerta del concorrente."},{"at":"02:05","competency":"Gestire le obiezioni","kind":"migliora","quote":"Anche noi possiamo farle uno sconto.","text":"Hai rincorso il prezzo. Prima ricorda ad Anna cosa perderebbe cambiando: sei anni senza un sinistro contestato."},{"at":"03:50","competency":"Gestire le obiezioni","kind":"positivo","quote":"Le mando il confronto per iscritto, così decide con calma.","text":"Hai tolto pressione e tenuto aperta la porta."}]'::jsonb);
insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r2', 's3', 'm4', '2026-10-22', 281, 3.7, '{"Ascolto attivo":3.9,"Tono di voce":3.4,"Gestire le obiezioni":3.8}'::jsonb, '[{"at":"00:15","competency":"Tono di voce","kind":"migliora","quote":"Sì, sì, ho capito, ma deve lasciarmi controllare.","text":"Il ritmo è accelerato quando il cliente ha alzato la voce: rallenta e abbassa il tono."},{"at":"01:20","competency":"Ascolto attivo","kind":"positivo","quote":"Mi dica tutto, la ascolto.","text":"Hai lasciato sfogare il cliente senza interromperlo."},{"at":"03:05","competency":"Gestire le obiezioni","kind":"positivo","quote":"Il bonifico parte venerdì: le mando la conferma via mail.","text":"Hai dato una data certa per il rimborso."}]'::jsonb);
insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r3', 's5', 'm7', '2026-10-21', 198, 3.2, '{"Argomentare con i dati":2.9,"Ascolto attivo":3.5}'::jsonb, '[{"at":"00:30","competency":"Argomentare con i dati","kind":"migliora","quote":"Auto Plus copre furto, incendio, cristalli, eventi atmosferici, atti vandalici…","text":"Hai elencato tutte le coperture: scegline due legate al bisogno della cliente."},{"at":"02:10","competency":"Ascolto attivo","kind":"positivo","quote":"Quanti chilometri fa in un anno, più o meno?","text":"Buona domanda aperta sulle abitudini di guida."}]'::jsonb);
insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r4', 's3', 'm8', '2026-10-19', 240, 2.6, '{"Ascolto attivo":2.8,"Tono di voce":2.4}'::jsonb, '[{"at":"00:20","competency":"Tono di voce","kind":"migliora","quote":"Signor Franco, si calmi, così non risolviamo.","text":"Chiedere di calmarsi alza la tensione: riconosci prima il disagio."},{"at":"01:40","competency":"Ascolto attivo","kind":"migliora","quote":"Il sistema dice che la pratica è in lavorazione.","text":"Hai risposto con la procedura prima di capire cosa serviva a Franco."},{"at":"03:10","competency":"Tono di voce","kind":"positivo","quote":"La richiamo io giovedì alle 10, dal mio numero diretto.","text":"Un impegno con giorno e ora: il cliente si è fermato."}]'::jsonb);
